suspend fun call(service: Service, req: Request): Reply = coroutineScope {
    val deferred = async { service.send(req) }   // the Deferred is the token
    val reply = deferred.await()                 // completion demuxed to this coroutine
    apply(req, reply)
}
// bridge: suspendCancellableCoroutine { cont -> service.send(req) { cont.resume(it) } }

